/**
 * Generate `.github/workflows/pi-tag.yml` from `.github/pi-tag.json`.
 *
 * The settings file is the policy; the YAML is a projection of it. Regenerating
 * must produce the same bytes, so a diff means somebody edited the workflow by
 * hand instead of the settings.
 *
 * The generated file has two jobs. `gate` is cheap and always runs when the
 * cheap `if:` expression passes; it decides in code whether this comment or
 * issue may trigger anything. `label` is the only job that costs a model call,
 * and it only starts when the gate says so — which is also why `concurrency`
 * lives on `label`: cancelling an in-flight tag because the bot posted its own
 * comment would be a self-inflicted race.
 */

import { SETTINGS_PATH, type Settings, WORKFLOW_PATH } from "./settings.ts";

export interface GenerateOptions {
	settings: Settings;
	/** Repository to fetch the tool from, `owner/repo`. */
	source?: string;
	/** Commit or tag to pin the tool to. */
	ref?: string;
	/** The App's bot login, when the identity is an App. */
	botLogin?: string;
}

const DEFAULT_SOURCE = "AutumnsGrove/pi-extensions";

export function botLoginFor(slug: string | undefined): string {
	return slug ? `${slug}[bot]` : "github-actions[bot]";
}

/** YAML-safe single-quoted scalar. */
function quote(value: string): string {
	return `'${value.replace(/'/g, "''")}'`;
}

function indent(text: string, spaces: number): string {
	const pad = " ".repeat(spaces);
	return text
		.split("\n")
		.map((line) => (line ? pad + line : line))
		.join("\n");
}

function checkoutTool(source: string, ref: string): string {
	// Split over a variable rather than one long line: the target repository
	// lints its YAML at 100 characters, and a URL is not a reason to opt out.
	return [
		`TOOL_DIR="$RUNNER_TEMP/pi-tag-src"`,
		`SOURCE_URL="https://github.com/${source}.git"`,
		`git init "$TOOL_DIR"`,
		`git -C "$TOOL_DIR" remote add origin "$SOURCE_URL"`,
		`git -C "$TOOL_DIR" fetch --depth 1 origin ${quote(ref)}`,
		`git -C "$TOOL_DIR" checkout --detach FETCH_HEAD`,
	].join("\n");
}

export function generateWorkflow(options: GenerateOptions): string {
	const { settings } = options;
	const source = options.source ?? DEFAULT_SOURCE;
	const ref = options.ref ?? settings.pi.packageRef ?? "main";
	const botLogin = options.botLogin ?? botLoginFor(undefined);
	const mention = settings.triggers.mention;

	const appToken =
		settings.identity === "app"
			? [
					"      - name: Mint the App token",
					"        id: app-token",
					"        uses: actions/create-github-app-token@v1",
					"        with:",
					"          app-id: ${{ secrets.PI_TAG_APP_ID }}",
					"          private-key: ${{ secrets.PI_TAG_APP_PRIVATE_KEY }}",
					"",
				].join("\n")
			: "";

	const token = settings.identity === "app" ? "${{ steps.app-token.outputs.token }}" : "${{ github.token }}";
	// In `label` the App slug is on the token step; in `gate` there is no token
	// yet, so the login comes from the repository variable the installer sets.
	const bot = settings.identity === "app" ? "${{ steps.app-token.outputs.app-slug }}[bot]" : botLogin;
	const botVar = settings.identity === "app" ? "${{ vars.PI_TAG_APP_SLUG }}[bot]" : botLogin;

	const workflow = `---
# Generated by pi-tag from ${SETTINGS_PATH} — edit the settings file, not this.
# Tool: ${source}@${ref}
name: pi-tag

"on":
  issues:
    types: [${settings.triggers.types.join(", ")}]
  issue_comment:
    types: [created]
  workflow_dispatch:
    inputs:
      issue_number:
        description: Issue number to tag
        required: true
      dry_run:
        description: Print what it would do and write nothing
        type: boolean
        default: true

permissions:
  contents: read
  issues: write

jobs:
  gate:
    # The cheap half of the trigger: no runner work for a comment that cannot
    # match. The precise rules live in gate.ts, which is tested.
    if: >-
      github.event_name != 'issue_comment' ||
      (github.event.issue.pull_request == null &&
      github.event.comment.user.type != 'Bot' &&
      contains(github.event.comment.body, ${quote(mention)}))
    runs-on: ubuntu-latest
    timeout-minutes: 5
    outputs:
      run: \${{ steps.gate.outputs.run }}
      reason: \${{ steps.gate.outputs.reason }}
      issue: \${{ steps.gate.outputs.issue }}
      fix: \${{ steps.gate.outputs.fix }}
      note: \${{ steps.gate.outputs.note }}
      dry_run: \${{ steps.gate.outputs.dry_run }}
    steps:
      - name: Check out the repository
        uses: actions/checkout@v5
        with:
          fetch-depth: 1
          persist-credentials: false
      - name: Check out the tool
        run: |
          set -euo pipefail
${indent(checkoutTool(source, ref), 10)}
      - name: Install pi
        run: npm install --global @earendil-works/pi-coding-agent@${settings.pi.version}
      - name: Decide whether to run
        id: gate
        env:
          # The gate runs before any App token exists, so the login comes from a
          # repository variable. It is belt and braces: gate.ts refuses any bot.
          PI_TAG_BOT_LOGIN: ${quote(botVar)}
        run: node "$RUNNER_TEMP/pi-tag-src/extensions/pi-tag/gate-cli.ts"

  label:
    needs: gate
    if: needs.gate.outputs.run == 'true'
    runs-on: ubuntu-latest
    timeout-minutes: ${settings.timeoutMinutes + 4}
    concurrency:
      # Keyed on the issue, so a second ${mention} wins. The bot's own comment
      # arrives in this same group, which is why the gate has to refuse it: the
      # next run would otherwise cancel the one that had just posted.
      group: pi-tag-\${{ needs.gate.outputs.issue }}
      cancel-in-progress: true
    steps:
      - name: Check out the repository
        uses: actions/checkout@v5
        with:
          fetch-depth: 1
          persist-credentials: false
      - name: Check out the tool
        run: |
          set -euo pipefail
${indent(checkoutTool(source, ref), 10)}
      - uses: actions/setup-node@v6
        with:
          node-version: "24"
      - name: Install pi
        run: npm install --global @earendil-works/pi-coding-agent@${settings.pi.version}
${appToken}      - name: Tag the issue
        id: tag
        env:
          GH_TOKEN: ${token}
          PI_TAG_API_KEY: \${{ secrets.PI_TAG_API_KEY }}
          ISSUE: \${{ needs.gate.outputs.issue }}
          IS_FIX: \${{ needs.gate.outputs.fix }}
          NOTE: \${{ needs.gate.outputs.note }}
          DRY_RUN: \${{ needs.gate.outputs.dry_run }}
        run: |
          set -euo pipefail
          args=(--repo "$GITHUB_WORKSPACE" --issue "$ISSUE")
          args+=(--provider ${quote(settings.provider)} --model ${quote(settings.model)})
          args+=(--thinking ${quote(settings.thinking)})
          args+=(--timeout ${settings.timeoutMinutes * 60})
          args+=(--author ${quote(bot)})
          args+=(--run-url "$GITHUB_SERVER_URL/$GITHUB_REPOSITORY/actions/runs/$GITHUB_RUN_ID")
          if [ "$IS_FIX" = "true" ]; then
            args+=(--fix "$NOTE")
          elif [ -n "$NOTE" ]; then
            args+=(--note "$NOTE")
          fi
          if [ "$DRY_RUN" != "true" ]; then
            args+=(--apply)
          fi
          node "$RUNNER_TEMP/pi-tag-src/extensions/pi-tag/cli.ts" "\${args[@]}"
      - name: Report a run that never finished
        # The CLI reports its own failures in the sticky comment and sets this
        # output. Only a run that died before it could (timeout, OOM) lands here.
        if: >-
          failure() && needs.gate.outputs.dry_run != 'true' &&
          steps.tag.outputs.handled != 'true'
        env:
          GH_TOKEN: ${token}
          ISSUE: \${{ needs.gate.outputs.issue }}
        run: |
          set -euo pipefail
          gh issue comment "$ISSUE" --body "$(cat <<'BODY'
          pi-tag could not finish: the job failed or timed out before it could
          say why. Check the labels on this issue, then comment ${mention} to
          try again.
          BODY
          )"
`;

	return workflow;
}

export function workflowPath(): string {
	return WORKFLOW_PATH;
}
